{
  "behavior": [
    {
      "when": "size_bytes < 0",
      "then": "False 반환 (음수 입력은 잘못된 크기이므로 거부)"
    },
    {
      "when": "size_bytes == 0",
      "then": "False 반환 (빈 파일은 거부)"
    },
    {
      "when": "size_bytes == 16",
      "then": "False 반환 (정확히 상한인 파일은 거부)"
    },
    {
      "when": "0 < size_bytes < 16",
      "then": "True 반환 (상한보다 작은 양수 파일은 허용)"
    },
    {
      "when": "size_bytes > 16",
      "then": "False 반환 (상한보다 큰 파일은 거부)"
    }
  ]
}
